import React, { useState, useEffect } from 'react';
import './Dashboard.css';
import VerifierPin from './VerifierPin';

function Dashboard({ allerVers, utilisateur }) {
  const [donnees, setDonnees] = useState(null);
  const [chargement, setChargement] = useState(true);
  const [onglet, setOnglet] = useState('apercu');
  const [pinVerifie, setPinVerifie] = useState(false);

  useEffect(() => {
    if (!utilisateur || utilisateur.role !== 'artiste') {
      allerVers('accueil');
      return;
    }

    fetch(`/api/dashboard/${utilisateur.id}`)
      .then(res => res.json())
      .then(data => {
        setDonnees(data);
        setChargement(false);
      })
      .catch(() => setChargement(false));
  }, [utilisateur]);

  if (!pinVerifie) {
    return (
      <VerifierPin
        utilisateur={utilisateur}
        titre="Accès Dashboard"
        onSuccess={() => setPinVerifie(true)}
        onCancel={() => allerVers('accueil')}
      />
    );
  }

  if (chargement) return (
    <div className="dashboard-page">
      <div className="chargement">Chargement du dashboard...</div>
    </div>
  );

  return (
    <div className="dashboard-page">
      <header className="header">
        <div className="logo" onClick={() => allerVers('accueil')}>🎵 Varim Music</div>
        <nav className="nav">
          <a href="#" onClick={() => allerVers('accueil')}>Accueil</a>
          <a href="#" onClick={() => allerVers('catalogue')}>Catalogue</a>
          <a href="#" className="actif">Mon Dashboard</a>
        </nav>
        <div className="auth-buttons">
          <span className="user-prenom">👋 {utilisateur?.prenom}</span>
          <button className="btn-publier" onClick={() => allerVers('upload')}>+ Publier</button>
          <button className="btn-login" onClick={() => {
            localStorage.removeItem('token');
            localStorage.removeItem('utilisateur');
            allerVers('accueil');
          }}>Déconnexion</button>
        </div>
      </header>

      <div className="dashboard-contenu">
        <h1 className="dashboard-titre">🎛️ Mon Dashboard</h1>
        <p className="dashboard-sous-titre">Bienvenue, {utilisateur?.prenom} !</p>

        {/* STATS PRINCIPALES */}
        <div className="stats-grille">
          <div className="stat-carte">
            <div className="stat-icone">🎵</div>
            <div className="stat-valeur">{donnees?.musiques?.length || 0}</div>
            <div className="stat-label">Musiques publiées</div>
          </div>
          <div className="stat-carte">
            <div className="stat-icone">🛒</div>
            <div className="stat-valeur">{donnees?.totaux?.total_ventes || 0}</div>
            <div className="stat-label">Total ventes</div>
          </div>
          <div className="stat-carte revenus" style={{cursor:'pointer'}} onClick={() => allerVers('retrait')}>
            <div className="stat-icone">💰</div>
            <div className="stat-valeur" style={{color:'#48bb78'}}>{donnees?.totaux?.total_revenus_nets || 0} FCFA</div>
            <div className="stat-label">Gains disponibles</div>
            <div style={{fontSize:'11px', color:'#4f9cf9', marginTop:'5px'}}>💸 Retirer →</div>
          </div>
          <div className="stat-carte">
            <div className="stat-icone">📤</div>
            <div className="stat-valeur" style={{color:'#f6ad55'}}>{donnees?.totaux?.total_retire || 0} FCFA</div>
            <div className="stat-label">Total retiré</div>
          </div>
        </div>

        {/* SOLDES PAR OPÉRATEUR */}
        <div className="soldes-operateurs">
          <div className="solde-op mtn">
            <span className="op-badge mtn">MTN</span>
            <span className="op-solde">{donnees?.totaux?.solde_mtn || 0} FCFA disponibles</span>
            {!utilisateur?.numero_mtn && (
              <span className="op-warning">⚠️ Numéro non configuré</span>
            )}
          </div>
          <div className="solde-op airtel">
            <span className="op-badge airtel">Airtel</span>
            <span className="op-solde">{donnees?.totaux?.solde_airtel || 0} FCFA disponibles</span>
            {!utilisateur?.numero_airtel && (
              <span className="op-warning">⚠️ Numéro non configuré</span>
            )}
          </div>
        </div>

        {/* ONGLETS */}
        <div className="dashboard-onglets">
          <button className={`onglet ${onglet === 'apercu' ? 'actif' : ''}`} onClick={() => setOnglet('apercu')}>
            🎵 Mes musiques
          </button>
          <button className={`onglet ${onglet === 'ventes' ? 'actif' : ''}`} onClick={() => setOnglet('ventes')}>
            🛒 Dernières ventes
          </button>
          <button className={`onglet ${onglet === 'notifications' ? 'actif' : ''}`} onClick={() => setOnglet('notifications')}>
            🔔 Notifications
          </button>
          <button className={`onglet ${onglet === 'retraits' ? 'actif' : ''}`} onClick={() => setOnglet('retraits')}>
            📋 Historique retraits
          </button>
        </div>

        {/* MES MUSIQUES */}
        {onglet === 'apercu' && (
          <div className="dashboard-section">
            <h2>🎵 Mes musiques</h2>
            {donnees?.musiques?.length === 0 ? (
              <div className="vide">
                <p>Vous n'avez pas encore publié de musique.</p>
                <button className="btn-publier-grand" onClick={() => allerVers('upload')}>
                  + Publier ma première musique
                </button>
              </div>
            ) : (
              <div className="musiques-liste">
                {donnees?.musiques?.map(musique => (
                  <div key={musique.id} className="musique-ligne">
                    <div className="musique-pochette">
                      {musique.pochette_url ? (
                        <img src={musique.pochette_url} alt={musique.titre} />
                      ) : (
                        <div className="pochette-defaut">
                          {musique.type === 'album' ? '💿' : '🎵'}
                        </div>
                      )}
                    </div>
                    <div className="musique-info">
                      <h3>{musique.titre}</h3>
                      <p>{musique.type === 'album' ? '💿 Album' : '🎵 Single'} — {musique.genre}</p>
                      <p className="musique-prix">{musique.prix} FCFA</p>
                    </div>
                    <div className="musique-stats">
                      <div className="mini-stat">
                        <span className="mini-val">{musique.nb_ventes_reel}</span>
                        <span className="mini-label">ventes</span>
                      </div>
                      <div className="mini-stat revenus">
                        <span className="mini-val">{musique.revenus_total} FCFA</span>
                        <span className="mini-label">revenus</span>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {/* DERNIÈRES VENTES */}
        {onglet === 'ventes' && (
          <div className="dashboard-section">
            <h2>🛒 Dernières ventes</h2>
            {donnees?.dernieresVentes?.length === 0 ? (
              <div className="vide">Aucune vente pour l'instant.</div>
            ) : (
              <div className="ventes-liste">
                {donnees?.dernieresVentes?.map(vente => (
                  <div key={vente.id} className="vente-ligne">
                    <div className="vente-info">
                      <span className="vente-titre">{vente.titre}</span>
                      <span className="vente-acheteur">acheté par {vente.acheteur_prenom}</span>
                      <span className="vente-operateur">
                        via <span className={`badge-op ${vente.operateur}`}>{vente.operateur?.toUpperCase()}</span>
                      </span>
                    </div>
                    <div className="vente-montant">
                      <span className="vente-revenu">+{vente.revenu_artiste} FCFA</span>
                      <span className="vente-date">
                        {new Date(vente.date_achat).toLocaleDateString('fr-FR')}
                      </span>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {/* NOTIFICATIONS GROUPÉES */}
        {onglet === 'notifications' && (
          <div className="dashboard-section">
            <h2>🔔 Notifications</h2>
            {donnees?.notifications?.length === 0 ? (
              <div className="vide">Aucune notification.</div>
            ) : (
              <div className="notifications-liste">
                {donnees?.notifications?.map((notif, index) => (
                  <div key={index} className="notif-ligne">
                    <span className="notif-icone">🛒</span>
                    <div className="notif-texte">
                      <strong>{notif.nb_achats} personne{notif.nb_achats > 1 ? 's ont' : ' a'} acheté</strong> {notif.titre}
                      <span className="notif-date">
                        — Dernier achat le {new Date(notif.derniere_date).toLocaleDateString('fr-FR')}
                      </span>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {/* HISTORIQUE RETRAITS */}
        {onglet === 'retraits' && (
          <div className="dashboard-section">
            <h2>📋 Historique des retraits</h2>
            <button
              className="btn-nouveau-retrait"
              onClick={() => allerVers('retrait')}
            >
              💸 Faire un retrait
            </button>
            {donnees?.historiqueRetraits?.length === 0 ? (
              <div className="vide">Aucun retrait effectué.</div>
            ) : (
              <table className="retrait-table">
                <thead>
                  <tr>
                    <th>Date</th>
                    <th>Opérateur</th>
                    <th>Montant</th>
                    <th>Numéro</th>
                    <th>Statut</th>
                  </tr>
                </thead>
                <tbody>
                  {donnees?.historiqueRetraits?.map(retrait => (
                    <tr key={retrait.id}>
                      <td>{new Date(retrait.date_demande).toLocaleDateString('fr-FR')}</td>
                      <td>
                        <span className={`badge-op ${retrait.operateur}`}>
                          {retrait.operateur.toUpperCase()}
                        </span>
                      </td>
                      <td className="montant-retrait">{retrait.montant} FCFA</td>
                      <td>+242 {retrait.numero_retrait}</td>
                      <td>
                        <span className={`statut ${retrait.statut}`}>
                          {retrait.statut === 'en_attente' ? '⏳ En attente' :
                           retrait.statut === 'traite' ? '✅ Traité' : '❌ Annulé'}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

export default Dashboard;
